/**
 * Worker-backed `node:sqlite` client: the `SqlClient` wrapper (compiler,
 * span attributes, transaction machinery) stays on the main thread while the
 * `Connection` internals execute in a dedicated worker thread
 * (`SqliteWorker.ts`), so long-running statements no longer stall the
 * server's event loop.
 *
 * The worker is spawned once per layer and torn down with the layer scope.
 * A worker crash fails in-flight requests as a defect and is fatal, matching
 * the blast radius of an in-process sqlite crash.
 *
 * @module NodeSqliteWorkerClient
 */
import * as NodeWorkerThreads from "node:worker_threads";

import * as NodeWorker from "@effect/platform-node/NodeWorker";
import * as Context from "effect/Context";
import * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Fiber from "effect/Fiber";
import * as Layer from "effect/Layer";
import * as Scope from "effect/Scope";
import * as Semaphore from "effect/Semaphore";
import * as Stream from "effect/Stream";
import * as Reactivity from "effect/unstable/reactivity/Reactivity";
import * as RpcClient from "effect/unstable/rpc/RpcClient";
import * as Client from "effect/unstable/sql/SqlClient";
import type { Connection } from "effect/unstable/sql/SqlConnection";
import { SqlError, ConnectionError } from "effect/unstable/sql/SqlError";
import * as Statement from "effect/unstable/sql/Statement";

import type { SqliteClientConfig } from "./NodeSqliteClient.ts";
import {
  checkNodeSqliteCompat,
  SqliteWorkerRpcs,
  UnsupportedNodeSqliteOperationError,
} from "./NodeSqliteConnection.ts";
import type { SqliteWorkerData } from "./NodeSqliteConnection.ts";

const ATTR_DB_SYSTEM_NAME = "db.system.name";

/**
 * In development the server runs directly from source (`node src/bin.ts`
 * with type stripping), so the worker entry is the sibling `.ts` file. In
 * the packed build (`vp pack`) this module becomes a chunk at the dist root
 * while the worker entry preserves its source-relative path, emitted at
 * `dist/persistence/SqliteWorker.mjs`.
 */
const workerEntryUrl = (): URL =>
  import.meta.url.endsWith(".ts")
    ? new URL("./SqliteWorker.ts", import.meta.url)
    : new URL("./persistence/SqliteWorker.mjs", import.meta.url);

const make = Effect.fnUntraced(function* (options: SqliteClientConfig) {
  yield* checkNodeSqliteCompat();

  const compiler = Statement.makeCompilerSqlite(options.transformQueryNames);
  const transformRows = options.transformResultNames
    ? Statement.defaultTransforms(options.transformResultNames).array
    : undefined;

  const workerData: SqliteWorkerData = {
    filename: options.filename,
    readonly: options.readonly ?? false,
    allowExtension: options.allowExtension ?? false,
    prepareCacheSize: options.prepareCacheSize,
    prepareCacheTTLMillis:
      options.prepareCacheTTL !== undefined
        ? Duration.toMillis(options.prepareCacheTTL)
        : undefined,
  };

  // The protocol (and the worker it spawns) is acquired in the layer scope,
  // so the worker lives exactly as long as the SqlClient layer.
  const protocol = yield* RpcClient.makeProtocolWorker({ size: 1, concurrency: 1 }).pipe(
    Effect.provide(
      NodeWorker.layer(() => new NodeWorkerThreads.Worker(workerEntryUrl(), { workerData })),
    ),
    Effect.mapError(
      (workerError) =>
        new SqlError({
          reason: new ConnectionError({
            message: "Failed to start sqlite worker",
            operation: "open",
            cause: workerError,
          }),
        }),
    ),
  );
  const rpc = yield* RpcClient.make(SqliteWorkerRpcs).pipe(
    Effect.provideService(RpcClient.Protocol, protocol),
  );

  const safeIntegers = Effect.withFiber<boolean>((fiber) =>
    Effect.succeed(Boolean(Context.get(fiber.context, Client.SafeIntegers))),
  );

  // A worker crash (or any other protocol failure) is fatal in v1, matching
  // today's in-process crash behaviour. Results come back as `unknown` over
  // the wire; the worker executes the same shared connection code the
  // in-process client uses, so the row-array shape is guaranteed.
  const executeWorker = (request: {
    readonly sql: string;
    readonly params: ReadonlyArray<unknown>;
    readonly raw: boolean;
    readonly noCache: boolean;
  }): Effect.Effect<ReadonlyArray<any>, SqlError> =>
    Effect.flatMap(safeIntegers, (safeIntegers) =>
      Effect.catchTag(rpc.Execute({ ...request, safeIntegers }), "RpcClientError", Effect.die),
    ) as Effect.Effect<ReadonlyArray<any>, SqlError>;

  const connection: Connection = {
    execute(sql, params, rowTransform) {
      const effect = executeWorker({ sql, params, raw: false, noCache: false });
      return rowTransform ? Effect.map(effect, rowTransform) : effect;
    },
    executeRaw(sql, params) {
      return executeWorker({ sql, params, raw: true, noCache: false });
    },
    executeValues(sql, params) {
      return Effect.flatMap(safeIntegers, (safeIntegers) =>
        Effect.catchTag(
          rpc.ExecuteValues({ sql, params, safeIntegers }),
          "RpcClientError",
          Effect.die,
        ),
      ) as Effect.Effect<ReadonlyArray<ReadonlyArray<unknown>>, SqlError>;
    },
    executeUnprepared(sql, params, rowTransform) {
      const effect = executeWorker({ sql, params: params ?? [], raw: false, noCache: true });
      return rowTransform ? Effect.map(effect, rowTransform) : effect;
    },
    executeStream(_sql, _params) {
      return Stream.die(new UnsupportedNodeSqliteOperationError());
    },
  };

  // Unlike the synchronous in-process client — where the permit can be
  // released before execution because a synchronous statement cannot be
  // interleaved — the async worker round trip makes the race window real: a
  // plain statement could otherwise land inside another fiber's open
  // transaction. Plain statements therefore hold the permit across the whole
  // round trip, while transaction statements use the unlocked connection
  // (the transaction scope already holds the permit, so plain statements
  // queue behind the open transaction exactly as before).
  const semaphore = yield* Semaphore.make(1);
  const withPermit = semaphore.withPermits(1);
  const lockedConnection: Connection = {
    execute: (sql, params, rowTransform) =>
      withPermit(connection.execute(sql, params, rowTransform)),
    executeRaw: (sql, params) => withPermit(connection.executeRaw(sql, params)),
    executeValues: (sql, params) => withPermit(connection.executeValues(sql, params)),
    executeUnprepared: (sql, params, rowTransform) =>
      withPermit(connection.executeUnprepared(sql, params, rowTransform)),
    executeStream: connection.executeStream,
  };

  const acquirer = Effect.succeed(lockedConnection);
  const transactionAcquirer = Effect.uninterruptibleMask((restore) => {
    const fiber = Fiber.getCurrent()!;
    const scope = Context.getUnsafe(fiber.context, Scope.Scope);
    return Effect.as(
      Effect.tap(restore(semaphore.take(1)), () => Scope.addFinalizer(scope, semaphore.release(1))),
      connection,
    );
  });

  return yield* Client.make({
    acquirer,
    compiler,
    transactionAcquirer,
    spanAttributes: [
      ...(options.spanAttributes ? Object.entries(options.spanAttributes) : []),
      [ATTR_DB_SYSTEM_NAME, "sqlite"],
    ],
    transformRows,
  });
});

export const layer = (config: SqliteClientConfig): Layer.Layer<Client.SqlClient, SqlError> =>
  Layer.effect(Client.SqlClient, make(config)).pipe(Layer.provide(Reactivity.layer));

/**
 * Worker-thread entrypoint hosting the synchronous `node:sqlite` connection.
 *
 * Spawned by `NodeSqliteWorkerClient` with a `SqliteWorkerData` payload in
 * `workerData`. Serves the `SqliteWorkerRpcs` protocol over the Effect worker
 * runner, so every statement executes off the server's main event loop.
 * Shutdown is parent-driven: the Rpc scope teardown sends the close signal
 * and the database close finalizer runs before the worker exits.
 *
 * @module SqliteWorker
 */
import * as NodeSqlite from "node:sqlite";
import * as NodeWorkerThreads from "node:worker_threads";

import * as NodeWorkerRunner from "@effect/platform-node/NodeWorkerRunner";
import * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as RpcServer from "effect/unstable/rpc/RpcServer";

import { makeRawConnection, SqliteWorkerRpcs } from "./NodeSqliteConnection.ts";
import type { SqliteWorkerData } from "./NodeSqliteConnection.ts";

const config = NodeWorkerThreads.workerData as SqliteWorkerData;

const HandlersLive = SqliteWorkerRpcs.toLayer(
  Effect.gen(function* () {
    const connection = yield* makeRawConnection(
      () =>
        new NodeSqlite.DatabaseSync(config.filename, {
          readOnly: config.readonly,
          allowExtension: config.allowExtension,
        }),
      {
        prepareCacheSize: config.prepareCacheSize,
        prepareCacheTTL:
          config.prepareCacheTTLMillis !== undefined
            ? Duration.millis(config.prepareCacheTTLMillis)
            : undefined,
      },
    );
    return SqliteWorkerRpcs.of({
      Execute: (request) => connection.execute(request.sql, request.params, request),
      ExecuteValues: (request) => connection.executeValues(request.sql, request.params, request),
    });
  }),
);

const MainLive = RpcServer.layer(SqliteWorkerRpcs).pipe(
  Layer.provide(HandlersLive),
  Layer.provide(RpcServer.layerProtocolWorkerRunner),
  Layer.provide(NodeWorkerRunner.layer),
);

Effect.runFork(Layer.launch(MainLive));

/**
 * Shared internals for the `node:sqlite` persistence clients: the synchronous
 * connection implementation (DatabaseSync + prepared-statement cache) and the
 * Rpc protocol used between the main-thread worker client and the sqlite
 * worker thread. Both `NodeSqliteClient` (in-process, used for `:memory:`
 * databases) and `SqliteWorker` (worker thread, used for file-backed
 * databases) execute statements through this module.
 *
 * @module NodeSqliteConnection
 */
import * as NodeSqlite from "node:sqlite";

import * as Cache from "effect/Cache";
import * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import { identity } from "effect/Function";
import * as Schema from "effect/Schema";
import * as Scope from "effect/Scope";
import * as Rpc from "effect/unstable/rpc/Rpc";
import * as RpcGroup from "effect/unstable/rpc/RpcGroup";
import { SqlError, classifySqliteError } from "effect/unstable/sql/SqlError";

export class UnsupportedNodeSqliteVersionError extends Schema.TaggedErrorClass<UnsupportedNodeSqliteVersionError>()(
  "UnsupportedNodeSqliteVersionError",
  {
    nodeVersion: Schema.String,
    requirement: Schema.String,
  },
) {
  override get message(): string {
    return `Node.js ${this.nodeVersion} is missing required node:sqlite APIs. Upgrade to ${this.requirement}.`;
  }
}

export class UnsupportedNodeSqliteOperationError extends Schema.TaggedErrorClass<UnsupportedNodeSqliteOperationError>()(
  "UnsupportedNodeSqliteOperationError",
  {},
) {
  override get message(): string {
    return "Node SQLite does not support executeStream.";
  }
}

/**
 * Verify that the current Node.js version includes the `node:sqlite` APIs
 * used by the sqlite clients — specifically `StatementSync.columns()` (added
 * in Node 22.16.0 / 23.11.0).
 *
 * @see https://github.com/nodejs/node/pull/57490
 */
export const checkNodeSqliteCompat = (): Effect.Effect<void> => {
  const parts = process.versions.node.split(".").map(Number);
  const major = parts[0] ?? 0;
  const minor = parts[1] ?? 0;
  const supported = (major === 22 && minor >= 16) || (major === 23 && minor >= 11) || major >= 24;

  if (!supported) {
    return Effect.die(
      new UnsupportedNodeSqliteVersionError({
        nodeVersion: process.versions.node,
        requirement: "Node.js >=22.16, >=23.11, or >=24",
      }),
    );
  }
  return Effect.void;
};

export interface NodeSqliteConnectionOptions {
  readonly prepareCacheSize?: number | undefined;
  readonly prepareCacheTTL?: Duration.Input | undefined;
}

export interface ExecuteOptions {
  /** Apply `setReadBigInts` so integer columns decode as bigints. */
  readonly safeIntegers: boolean;
  /** Return the raw `StatementResultingChanges` for non-row statements. */
  readonly raw: boolean;
  /** Prepare the statement fresh, bypassing the prepare cache. */
  readonly noCache: boolean;
}

/**
 * The synchronous statement executor shared by the in-process client and the
 * sqlite worker. Per-request behaviour (safe integers, raw results, value
 * arrays, cache bypass) is passed explicitly so callers on either side of the
 * worker boundary resolve it in their own context.
 */
export interface NodeSqliteRawConnection {
  readonly execute: (
    sql: string,
    params: ReadonlyArray<unknown>,
    options: ExecuteOptions,
  ) => Effect.Effect<ReadonlyArray<any>, SqlError>;
  readonly executeValues: (
    sql: string,
    params: ReadonlyArray<unknown>,
    options: { readonly safeIntegers: boolean },
  ) => Effect.Effect<ReadonlyArray<ReadonlyArray<unknown>>, SqlError>;
}

export const makeRawConnection = Effect.fnUntraced(function* (
  openDatabase: () => NodeSqlite.DatabaseSync,
  options?: NodeSqliteConnectionOptions,
): Effect.fn.Return<NodeSqliteRawConnection, SqlError, Scope.Scope> {
  const scope = yield* Effect.scope;
  const db = yield* Effect.try({
    try: openDatabase,
    catch: (cause) =>
      new SqlError({
        reason: classifySqliteError(cause, {
          message: "Failed to open database",
          operation: "open",
        }),
      }),
  });
  yield* Scope.addFinalizer(
    scope,
    Effect.try({
      try: () => db.close(),
      catch: (cause) =>
        new SqlError({
          reason: classifySqliteError(cause, {
            message: "Failed to close database",
            operation: "close",
          }),
        }),
    }).pipe(Effect.orDie),
  );

  const statementReaderCache = new WeakMap<NodeSqlite.StatementSync, boolean>();
  const hasRows = (statement: NodeSqlite.StatementSync): boolean => {
    const cached = statementReaderCache.get(statement);
    if (cached !== undefined) {
      return cached;
    }
    const value = statement.columns().length > 0;
    statementReaderCache.set(statement, value);
    return value;
  };

  const prepare = (sql: string) =>
    Effect.try({
      try: () => db.prepare(sql),
      catch: (cause) =>
        new SqlError({
          reason: classifySqliteError(cause, {
            message: "Failed to prepare statement",
            operation: "prepare",
          }),
        }),
    });

  const prepareCache = yield* Cache.make({
    capacity: options?.prepareCacheSize ?? 200,
    timeToLive: options?.prepareCacheTTL ?? Duration.minutes(10),
    lookup: prepare,
  });

  const runStatement = (
    statement: NodeSqlite.StatementSync,
    params: ReadonlyArray<unknown>,
    options: { readonly safeIntegers: boolean; readonly raw?: boolean },
  ): Effect.Effect<ReadonlyArray<any>, SqlError> =>
    Effect.suspend(() => {
      try {
        statement.setReadBigInts(options.safeIntegers);
        if (hasRows(statement)) {
          return Effect.succeed(statement.all(...(params as any)));
        }
        const result = statement.run(...(params as any));
        return Effect.succeed(options.raw ? (result as unknown as ReadonlyArray<any>) : []);
      } catch (cause) {
        return Effect.fail(
          new SqlError({
            reason: classifySqliteError(cause, {
              message: "Failed to execute statement",
              operation: "execute",
            }),
          }),
        );
      }
    });

  return identity<NodeSqliteRawConnection>({
    execute: (sql, params, options) =>
      Effect.flatMap(options.noCache ? prepare(sql) : Cache.get(prepareCache, sql), (statement) =>
        runStatement(statement, params, options),
      ),
    executeValues: (sql, params, options) =>
      Effect.acquireUseRelease(
        Cache.get(prepareCache, sql),
        (statement) =>
          Effect.try({
            try: () => {
              statement.setReadBigInts(options.safeIntegers);
              if (hasRows(statement)) {
                statement.setReturnArrays(true);
                // Safe to cast to array after we've setReturnArrays(true)
                return statement.all(...(params as any)) as unknown as ReadonlyArray<
                  ReadonlyArray<unknown>
                >;
              }
              statement.run(...(params as any));
              return [];
            },
            catch: (cause) =>
              new SqlError({
                reason: classifySqliteError(cause, {
                  message: "Failed to execute statement",
                  operation: "execute",
                }),
              }),
          }),
        (statement) =>
          Effect.try({
            try: () => {
              if (hasRows(statement)) {
                statement.setReturnArrays(false);
              }
            },
            catch: (cause) =>
              new SqlError({
                reason: classifySqliteError(cause, {
                  message: "Failed to reset statement result mode",
                  operation: "resetResultMode",
                }),
              }),
          }).pipe(Effect.orDie),
      ),
  });
});

/**
 * Configuration handed to the sqlite worker via `workerData`. Durations are
 * flattened to milliseconds so the payload is structured-clone friendly.
 */
export interface SqliteWorkerData {
  readonly filename: string;
  readonly readonly: boolean;
  readonly allowExtension: boolean;
  readonly prepareCacheSize?: number | undefined;
  readonly prepareCacheTTLMillis?: number | undefined;
}

/**
 * Rpc protocol between the main-thread proxy `Connection` and the sqlite
 * worker. Payloads and results are passed through as-is — rows are
 * primitives / strings / Uint8Arrays / bigints, all of which structured
 * clone handles natively. `Schema.Any` (not `Schema.Unknown`) is load-
 * bearing: the Rpc pipeline encodes via `Schema.toCodecJson`, under which
 * `Unknown` maps to a JSON-value validator that rejects bigints and
 * Uint8Arrays, while `Any` passes values through untouched. `SqlError` is a
 * Schema tagged error, so it round-trips the boundary intact.
 */
export const SqliteWorkerRpcs = RpcGroup.make(
  Rpc.make("Execute", {
    payload: {
      sql: Schema.String,
      params: Schema.Array(Schema.Any),
      safeIntegers: Schema.Boolean,
      raw: Schema.Boolean,
      noCache: Schema.Boolean,
    },
    success: Schema.Any,
    error: SqlError,
  }),
  Rpc.make("ExecuteValues", {
    payload: {
      sql: Schema.String,
      params: Schema.Array(Schema.Any),
      safeIntegers: Schema.Boolean,
    },
    success: Schema.Any,
    error: SqlError,
  }),
);

import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as FileSystem from "effect/FileSystem";
import * as Path from "effect/Path";
import * as SqlClient from "effect/unstable/sql/SqlClient";
import type { SqlError } from "effect/unstable/sql/SqlError";

import { runMigrations } from "../Migrations.ts";
import { ServerConfig } from "../../config.ts";

type RuntimeSqliteLayerConfig = {
  readonly filename: string;
  readonly spanAttributes?: Record<string, unknown>;
};

type Loader = {
  layer: (config: RuntimeSqliteLayerConfig) => Layer.Layer<SqlClient.SqlClient, SqlError>;
};
const defaultSqliteClientLoaders = {
  bun: () => import("@effect/sql-sqlite-bun/SqliteClient"),
  // File-backed node databases run in a dedicated worker thread so long
  // statements cannot stall the main event loop; :memory: databases (tests)
  // stay on the fast in-process synchronous client.
  node: () => import("../NodeSqliteWorkerClient.ts"),
  nodeMemory: () => import("../NodeSqliteClient.ts"),
} satisfies Record<string, () => Promise<Loader>>;

const makeRuntimeSqliteLayer = Effect.fn("makeRuntimeSqliteLayer")(function* (
  config: RuntimeSqliteLayerConfig,
) {
  const runtime =
    process.versions.bun !== undefined
      ? "bun"
      : config.filename === ":memory:"
        ? "nodeMemory"
        : "node";
  const loader = defaultSqliteClientLoaders[runtime];
  const clientModule = yield* Effect.promise<Loader>(loader);
  return clientModule.layer(config);
}, Layer.unwrap);

const setup = Layer.effectDiscard(
  Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    yield* sql`PRAGMA journal_mode = WAL;`;
    // The server holds a long-lived connection while workstream mutations run
    // as separate short-lived CLI processes (cli/orchestrationMutation, goal,
    // project) against this same file. SQLite permits one writer at a time, so
    // without a busy timeout any overlap — e.g. a CLI mutation landing during
    // the server's high-frequency token-usage writes — fails instantly with
    // "database is locked". Wait for the lock instead of failing on contention.
    yield* sql`PRAGMA busy_timeout = 5000;`;
    yield* sql`PRAGMA foreign_keys = ON;`;
    yield* runMigrations();
  }),
);

export const makeSqlitePersistenceLive = Effect.fn("makeSqlitePersistenceLive")(function* (
  dbPath: string,
) {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  yield* fs.makeDirectory(path.dirname(dbPath), { recursive: true });

  return Layer.provideMerge(
    setup,
    makeRuntimeSqliteLayer({
      filename: dbPath,
      spanAttributes: {
        "db.name": path.basename(dbPath),
        "service.name": "t3-server",
      },
    }),
  );
}, Layer.unwrap);

export const SqlitePersistenceMemory = Layer.provideMerge(
  setup,
  makeRuntimeSqliteLayer({ filename: ":memory:" }),
);

export const layerConfig = Layer.unwrap(
  Effect.map(Effect.service(ServerConfig), ({ dbPath }) => makeSqlitePersistenceLive(dbPath)),
);

/**
 * Shared live/offline orchestration-command dispatch for CLI mutations.
 *
 * Prefers a running server (so writes reach its in-memory projections and
 * shell stream immediately); falls back to an in-process orchestration engine
 * only when no live server answers. Used by the `project` and `goal` CLIs.
 */
import {
  AuthAdministrativeScopes,
  EnvironmentHttpApi,
  EnvironmentHttpCommonError,
  type ClientOrchestrationCommand,
  type OrchestrationReadModel,
} from "@t3tools/contracts";
import * as Console from "effect/Console";
import * as Crypto from "effect/Crypto";
import * as Data from "effect/Data";
import * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Exit from "effect/Exit";
import * as FileSystem from "effect/FileSystem";
import * as Layer from "effect/Layer";
import * as Option from "effect/Option";
import * as Path from "effect/Path";
import * as References from "effect/References";
import * as Schema from "effect/Schema";
import { GlobalFlag } from "effect/unstable/cli";
import { FetchHttpClient, HttpClient, HttpClientError } from "effect/unstable/http";
import * as HttpApiClient from "effect/unstable/httpapi/HttpApiClient";

import * as EnvironmentAuth from "../auth/EnvironmentAuth.ts";
import { ServerConfig } from "../config.ts";
import { OrchestrationEngineService } from "../orchestration/Services/OrchestrationEngine.ts";
import { ProjectionSnapshotQuery } from "../orchestration/Services/ProjectionSnapshotQuery.ts";
import { OrchestrationLayerLive } from "../orchestration/runtimeLayer.ts";
import { layerConfig as SqlitePersistenceLayerLive } from "../persistence/Layers/Sqlite.ts";
import * as RepositoryIdentityResolver from "../project/RepositoryIdentityResolver.ts";
import {
  clearPersistedServerRuntimeState,
  readPersistedServerRuntimeState,
} from "../serverRuntimeState.ts";
import * as WorkspacePaths from "../workspace/WorkspacePaths.ts";
import { type CliAuthLocationFlags, resolveCliAuthConfig } from "./config.ts";

export type OrchestrationCommandExecutionMode = "live" | "offline";

export class OrchestrationCliError extends Data.TaggedError("OrchestrationCliError")<{
  readonly message: string;
}> {}

export const orchestrationCliUuid = Crypto.Crypto.pipe(
  Effect.flatMap((crypto) => crypto.randomUUIDv4),
  Effect.mapError(
    () => new OrchestrationCliError({ message: "Failed to generate a command identifier." }),
  ),
);

const CliRuntimeLive = Layer.mergeAll(
  WorkspacePaths.layer,
  OrchestrationLayerLive.pipe(
    Layer.provideMerge(RepositoryIdentityResolver.layer),
    Layer.provideMerge(SqlitePersistenceLayerLive),
  ),
);

const LIVE_SERVER_TIMEOUT = Duration.seconds(1);
const isEnvironmentHttpCommonError = Schema.is(EnvironmentHttpCommonError);

const withCliSessionToken = <A, E, R>(
  environmentAuth: EnvironmentAuth.EnvironmentAuth["Service"],
  run: (token: string) => Effect.Effect<A, E, R>,
) =>
  Effect.acquireUseRelease(
    environmentAuth.issueSession({ scopes: AuthAdministrativeScopes, label: "t3 cli" }),
    (issued) => run(issued.token),
    (issued) => environmentAuth.revokeSession(issued.sessionId).pipe(Effect.ignore({ log: true })),
  );

const withLiveServerTimeout = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
  effect.pipe(Effect.timeout(LIVE_SERVER_TIMEOUT));

const failLiveServerRequest = (cause: unknown) => {
  if (isEnvironmentHttpCommonError(cause)) {
    return Effect.fail(
      new OrchestrationCliError({
        message: `Server request failed (${cause.code}, trace ${cause.traceId}).`,
      }),
    );
  }
  if (HttpClientError.isHttpClientError(cause) && cause.response !== undefined) {
    return Effect.fail(
      new OrchestrationCliError({
        message: `Server request failed with undeclared status ${cause.response.status}.`,
      }),
    );
  }
  return Effect.fail(
    new OrchestrationCliError({ message: `Failed to call running server: ${String(cause)}.` }),
  );
};

const makeLiveServerClient = (origin: string) =>
  HttpApiClient.make(EnvironmentHttpApi, { baseUrl: origin });

const fetchLiveOrchestrationSnapshot = (origin: string, bearerToken: string) =>
  Effect.gen(function* () {
    const client = yield* makeLiveServerClient(origin);
    return yield* client.orchestration.snapshot({
      headers: { authorization: `Bearer ${bearerToken}` },
    });
  }).pipe(withLiveServerTimeout, Effect.catch(failLiveServerRequest));

const dispatchLiveOrchestrationCommand = (
  origin: string,
  bearerToken: string,
  command: ClientOrchestrationCommand,
) =>
  Effect.gen(function* () {
    const client = yield* makeLiveServerClient(origin);
    yield* client.orchestration.dispatch({
      headers: { authorization: `Bearer ${bearerToken}` },
      payload: command,
    } as Parameters<typeof client.orchestration.dispatch>[0]);
  }).pipe(withLiveServerTimeout, Effect.catch(failLiveServerRequest));

const getOfflineSnapshot = Effect.fn("getOfflineSnapshot")(function* () {
  const projectionSnapshotQuery = yield* ProjectionSnapshotQuery;
  return yield* projectionSnapshotQuery.getSnapshot();
});

const tryResolveLiveExecutionMode = Effect.fn("tryResolveLiveExecutionMode")(function* (
  environmentAuth: EnvironmentAuth.EnvironmentAuth["Service"],
  config: ServerConfig["Service"],
) {
  const runtimeState = yield* readPersistedServerRuntimeState(config.serverRuntimeStatePath);
  if (Option.isNone(runtimeState)) {
    return Option.none<{ readonly origin: string }>();
  }
  const attempt = withCliSessionToken(environmentAuth, (token) =>
    fetchLiveOrchestrationSnapshot(runtimeState.value.origin, token).pipe(
      Effect.as({ origin: runtimeState.value.origin }),
    ),
  );
  const attempted = yield* Effect.exit(attempt);
  if (Exit.isSuccess(attempted)) {
    return Option.some(attempted.value);
  }
  yield* clearPersistedServerRuntimeState(config.serverRuntimeStatePath);
  return Option.none<{ readonly origin: string }>();
});

export type OrchestrationMutationDispatch<Cmd extends ClientOrchestrationCommand> = (
  command: Cmd,
) => Effect.Effect<void, Error, FileSystem.FileSystem | HttpClient.HttpClient | Path.Path>;

export interface OrchestrationMutationInput<Cmd extends ClientOrchestrationCommand> {
  readonly snapshot: OrchestrationReadModel;
  readonly dispatch: OrchestrationMutationDispatch<Cmd>;
  readonly mode: OrchestrationCommandExecutionMode;
}

export const runOrchestrationMutation = <Cmd extends ClientOrchestrationCommand>(
  flags: CliAuthLocationFlags,
  run: (
    input: OrchestrationMutationInput<Cmd>,
  ) => Effect.Effect<
    string,
    Error,
    | Crypto.Crypto
    | FileSystem.FileSystem
    | HttpClient.HttpClient
    | Path.Path
    | WorkspacePaths.WorkspacePaths
  >,
) =>
  Effect.gen(function* () {
    const logLevel = yield* GlobalFlag.LogLevel;
    const config = yield* resolveCliAuthConfig(flags, logLevel);
    const minimumLogLevel = config.logLevel;

    return yield* Effect.gen(function* () {
      const environmentAuth = yield* EnvironmentAuth.EnvironmentAuth;
      const liveMode = yield* tryResolveLiveExecutionMode(environmentAuth, config);

      if (Option.isSome(liveMode)) {
        return yield* withCliSessionToken(environmentAuth, (token) =>
          Effect.gen(function* () {
            const snapshot = yield* fetchLiveOrchestrationSnapshot(liveMode.value.origin, token);
            const output = yield* run({
              snapshot,
              dispatch: (command) =>
                dispatchLiveOrchestrationCommand(liveMode.value.origin, token, command),
              mode: "live",
            });
            yield* Console.log(output);
          }),
        );
      }

      const offlineRuntimeLayer = CliRuntimeLive.pipe(
        Layer.provide(Layer.succeed(ServerConfig, config)),
        Layer.provide(Layer.succeed(References.MinimumLogLevel, minimumLogLevel)),
      );

      return yield* Effect.gen(function* () {
        const snapshot = yield* getOfflineSnapshot();
        const orchestrationEngine = yield* OrchestrationEngineService;
        const output = yield* run({
          snapshot,
          dispatch: (command) =>
            orchestrationEngine.dispatch(
              command as Parameters<typeof orchestrationEngine.dispatch>[0],
            ),
          mode: "offline",
        });
        yield* Console.log(output);
      }).pipe(Effect.provide(offlineRuntimeLayer));
    }).pipe(
      Effect.provide(
        Layer.mergeAll(EnvironmentAuth.runtimeLayer, WorkspacePaths.layer).pipe(
          Layer.provideMerge(FetchHttpClient.layer),
          Layer.provide(Layer.succeed(ServerConfig, config)),
          Layer.provide(Layer.succeed(References.MinimumLogLevel, minimumLogLevel)),
        ),
      ),
    );
  });

import type {
  GoalId,
  OrchestrationEvent,
  OrchestrationReadModel,
  ProjectId,
  ThreadId,
} from "@t3tools/contracts";
import { OrchestrationCommand } from "@t3tools/contracts";
import * as Cause from "effect/Cause";
import * as Clock from "effect/Clock";
import * as Crypto from "effect/Crypto";
import * as DateTime from "effect/DateTime";
import * as Deferred from "effect/Deferred";
import * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Exit from "effect/Exit";
import * as Layer from "effect/Layer";
import * as Metric from "effect/Metric";
import * as Option from "effect/Option";
import * as PubSub from "effect/PubSub";
import * as Queue from "effect/Queue";
import * as Schema from "effect/Schema";
import * as Stream from "effect/Stream";
import * as SqlClient from "effect/unstable/sql/SqlClient";

import {
  metricAttributes,
  orchestrationCommandAckDuration,
  orchestrationCommandsTotal,
  orchestrationCommandDuration,
} from "../../observability/Metrics.ts";
import { toPersistenceSqlError } from "../../persistence/Errors.ts";
import { OrchestrationEventStore } from "../../persistence/Services/OrchestrationEventStore.ts";
import { OrchestrationCommandReceiptRepository } from "../../persistence/Services/OrchestrationCommandReceipts.ts";
import {
  OrchestrationCommandDeferredError,
  OrchestrationCommandInvariantError,
  OrchestrationCommandPreviouslyRejectedError,
  type OrchestrationDispatchError,
  type OrchestrationProjectorDecodeError,
} from "../Errors.ts";
import { decideOrchestrationCommand } from "../decider.ts";
import { isThreadIdle } from "../threadIdle.ts";
import { createEmptyReadModel, projectEvent } from "../projector.ts";
import { OrchestrationProjectionPipeline } from "../Services/ProjectionPipeline.ts";
import { ProjectionSnapshotQuery } from "../Services/ProjectionSnapshotQuery.ts";
import {
  OrchestrationEngineService,
  type OrchestrationEngineShape,
} from "../Services/OrchestrationEngine.ts";
const isOrchestrationCommandPreviouslyRejectedError = Schema.is(
  OrchestrationCommandPreviouslyRejectedError,
);
const isOrchestrationCommandInvariantError = Schema.is(OrchestrationCommandInvariantError);

interface CommandEnvelope {
  command: OrchestrationCommand;
  result: Deferred.Deferred<{ sequence: number }, OrchestrationDispatchError>;
  startedAtMs: number;
}

function commandToAggregateRef(command: OrchestrationCommand): {
  readonly aggregateKind: "project" | "goal" | "thread";
  readonly aggregateId: ProjectId | GoalId | ThreadId;
} {
  switch (command.type) {
    case "project.create":
    case "project.meta.update":
    case "project.delete":
      return {
        aggregateKind: "project",
        aggregateId: command.projectId,
      };
    case "goal.create":
    case "goal.meta.update":
    case "goal.archive":
    case "goal.unarchive":
    case "goal.delete":
    case "goal.task.create":
    case "goal.task.update":
    case "goal.task.delete":
      return {
        aggregateKind: "goal",
        aggregateId: command.goalId,
      };
    default:
      return {
        aggregateKind: "thread",
        aggregateId: command.threadId,
      };
  }
}

const makeOrchestrationEngine = Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;
  const eventStore = yield* OrchestrationEventStore;
  const commandReceiptRepository = yield* OrchestrationCommandReceiptRepository;
  const projectionPipeline = yield* OrchestrationProjectionPipeline;
  const projectionSnapshotQuery = yield* ProjectionSnapshotQuery;
  const crypto = yield* Crypto.Crypto;

  const nowIso = Effect.map(DateTime.now, DateTime.formatIso);
  let commandReadModel = createEmptyReadModel(yield* nowIso);

  const commandQueue = yield* Queue.unbounded<CommandEnvelope>();
  const eventPubSub = yield* PubSub.unbounded<OrchestrationEvent>();

  const projectEventsOntoReadModel = (
    baseReadModel: OrchestrationReadModel,
    events: ReadonlyArray<OrchestrationEvent>,
  ): Effect.Effect<OrchestrationReadModel, OrchestrationProjectorDecodeError, never> =>
    Effect.gen(function* () {
      let nextReadModel = baseReadModel;
      for (const event of events) {
        nextReadModel = yield* projectEvent(nextReadModel, event);
      }
      return nextReadModel;
    });

  const processEnvelope = (envelope: CommandEnvelope): Effect.Effect<void> => {
    const dispatchStartSequence = commandReadModel.snapshotSequence;
    let processingStartedAtMs = 0;
    const aggregateRef = commandToAggregateRef(envelope.command);
    const baseMetricAttributes = {
      commandType: envelope.command.type,
      aggregateKind: aggregateRef.aggregateKind,
    } as const;
    const reconcileReadModelAfterDispatchFailure = Effect.gen(function* () {
      const persistedEvents = yield* Stream.runCollect(
        eventStore.readFromSequence(dispatchStartSequence),
      ).pipe(Effect.map((chunk): OrchestrationEvent[] => Array.from(chunk)));
      if (persistedEvents.length === 0) {
        return;
      }

      commandReadModel = yield* projectEventsOntoReadModel(commandReadModel, persistedEvents);

      for (const persistedEvent of persistedEvents) {
        yield* PubSub.publish(eventPubSub, persistedEvent);
      }
    });

    return Effect.exit(
      Effect.gen(function* () {
        processingStartedAtMs = yield* Clock.currentTimeMillis;
        yield* Effect.annotateCurrentSpan({
          "orchestration.command_id": envelope.command.commandId,
          "orchestration.command_type": envelope.command.type,
          "orchestration.aggregate_kind": aggregateRef.aggregateKind,
          "orchestration.aggregate_id": aggregateRef.aggregateId,
        });

        const existingReceipt = yield* commandReceiptRepository.getByCommandId({
          commandId: envelope.command.commandId,
        });
        if (Option.isSome(existingReceipt)) {
          if (existingReceipt.value.status === "accepted") {
            return {
              sequence: existingReceipt.value.resultSequence,
            };
          }
          return yield* new OrchestrationCommandPreviouslyRejectedError({
            commandId: envelope.command.commandId,
            detail: existingReceipt.value.error ?? "Previously rejected.",
          });
        }

        // Atomic idle gate (D-notify decision 3): a dispatcher-injected wake
        // (`requireIdle`) must only land on an idle parent. The dispatcher's
        // pre-filter checks idleness at snapshot-read time, but a real prompt
        // can be committed in the serialized queue between that read and this
        // command. Re-check here against the just-committed state (read-model
        // session/active-turn + the durable pending-turn-start projection) so
        // the wake cannot clobber an in-flight or just-requested parent turn.
        // A busy parent is *deferred*, not rejected: we fail without writing a
        // receipt, so the deterministic wake command id stays redeliverable
        // when the parent next goes idle (drained on `thread.session-set`).
        if (
          envelope.command.type === "thread.turn.start" &&
          envelope.command.requireIdle === true
        ) {
          const idleCommand = envelope.command;
          const pendingTurnStartThreadIds =
            yield* projectionSnapshotQuery.getPendingTurnStartThreadIds();
          const target = commandReadModel.threads.find(
            (thread) => thread.id === idleCommand.threadId,
          );
          if (target === undefined || !isThreadIdle(target, pendingTurnStartThreadIds)) {
            return yield* new OrchestrationCommandDeferredError({
              commandType: idleCommand.type,
              detail: `Idle-gated turn-start for thread '${idleCommand.threadId}' deferred: target is not idle.`,
            });
          }
        }

        const eventBase = yield* decideOrchestrationCommand({
          command: envelope.command,
          readModel: commandReadModel,
        }).pipe(
          Effect.provideService(Crypto.Crypto, crypto),
          Effect.mapError((cause) =>
            isOrchestrationCommandInvariantError(cause)
              ? cause
              : new OrchestrationCommandInvariantError({
                  commandType: envelope.command.type,
                  detail: "Failed to generate an event identifier.",
                  cause,
                }),
          ),
        );
        const eventBases = Array.isArray(eventBase) ? eventBase : [eventBase];
        const committedCommand = yield* sql
          .withTransaction(
            Effect.gen(function* () {
              const committedEvents: OrchestrationEvent[] = [];
              let nextCommandReadModel = commandReadModel;

              for (const nextEvent of eventBases) {
                const savedEvent = yield* eventStore.append(nextEvent);
                nextCommandReadModel = yield* projectEvent(nextCommandReadModel, savedEvent);
                yield* projectionPipeline.projectEvent(savedEvent);
                committedEvents.push(savedEvent);
              }

              const lastSavedEvent = committedEvents.at(-1) ?? null;
              if (lastSavedEvent === null) {
                return yield* new OrchestrationCommandInvariantError({
                  commandType: envelope.command.type,
                  detail: "Command produced no events.",
                });
              }

              yield* commandReceiptRepository.upsert({
                commandId: envelope.command.commandId,
                aggregateKind: lastSavedEvent.aggregateKind,
                aggregateId: lastSavedEvent.aggregateId,
                acceptedAt: lastSavedEvent.occurredAt,
                resultSequence: lastSavedEvent.sequence,
                status: "accepted",
                error: null,
              });

              return {
                committedEvents,
                lastSequence: lastSavedEvent.sequence,
                nextCommandReadModel,
              } as const;
            }),
          )
          .pipe(
            Effect.catchTag("SqlError", (sqlError) =>
              Effect.fail(
                toPersistenceSqlError("OrchestrationEngine.processEnvelope:transaction")(sqlError),
              ),
            ),
          );

        commandReadModel = committedCommand.nextCommandReadModel;
        for (const [index, event] of committedCommand.committedEvents.entries()) {
          yield* PubSub.publish(eventPubSub, event);
          if (index === 0) {
            yield* Metric.update(
              Metric.withAttributes(
                orchestrationCommandAckDuration,
                metricAttributes({
                  ...baseMetricAttributes,
                  ackEventType: event.type,
                }),
              ),
              Duration.millis(Math.max(0, (yield* Clock.currentTimeMillis) - envelope.startedAtMs)),
            );
          }
        }
        return { sequence: committedCommand.lastSequence };
      }).pipe(Effect.withSpan(`orchestration.command.${envelope.command.type}`)),
    ).pipe(
      Effect.flatMap((exit) =>
        Effect.gen(function* () {
          const outcome = Exit.isSuccess(exit)
            ? "success"
            : Cause.hasInterruptsOnly(exit.cause)
              ? "interrupt"
              : "failure";
          yield* Metric.update(
            Metric.withAttributes(
              orchestrationCommandDuration,
              metricAttributes(baseMetricAttributes),
            ),
            Duration.millis(Math.max(0, (yield* Clock.currentTimeMillis) - processingStartedAtMs)),
          );
          yield* Metric.update(
            Metric.withAttributes(
              orchestrationCommandsTotal,
              metricAttributes({
                ...baseMetricAttributes,
                outcome,
              }),
            ),
            1,
          );

          if (Exit.isSuccess(exit)) {
            yield* Deferred.succeed(envelope.result, exit.value);
            return;
          }

          const error = Cause.squash(exit.cause) as OrchestrationDispatchError;
          if (!isOrchestrationCommandPreviouslyRejectedError(error)) {
            yield* reconcileReadModelAfterDispatchFailure.pipe(
              Effect.catch(() =>
                Effect.logWarning(
                  "failed to reconcile orchestration read model after dispatch failure",
                ).pipe(
                  Effect.annotateLogs({
                    commandId: envelope.command.commandId,
                    snapshotSequence: commandReadModel.snapshotSequence,
                  }),
                ),
              ),
            );

            if (isOrchestrationCommandInvariantError(error)) {
              yield* commandReceiptRepository
                .upsert({
                  commandId: envelope.command.commandId,
                  aggregateKind: aggregateRef.aggregateKind,
                  aggregateId: aggregateRef.aggregateId,
                  acceptedAt: yield* nowIso,
                  resultSequence: commandReadModel.snapshotSequence,
                  status: "rejected",
                  error: error.message,
                })
                .pipe(Effect.catch(() => Effect.void));
            }
          }

          yield* Deferred.fail(envelope.result, error);
        }),
      ),
    );
  };

  yield* projectionPipeline.bootstrap;
  commandReadModel = yield* projectionSnapshotQuery.getCommandReadModel();

  const worker = Effect.forever(Queue.take(commandQueue).pipe(Effect.flatMap(processEnvelope)));
  yield* Effect.forkScoped(worker);
  yield* Effect.logDebug("orchestration engine started").pipe(
    Effect.annotateLogs({ sequence: commandReadModel.snapshotSequence }),
  );

  const readEvents: OrchestrationEngineShape["readEvents"] = (fromSequenceExclusive) =>
    eventStore.readFromSequence(fromSequenceExclusive);

  const dispatch: OrchestrationEngineShape["dispatch"] = (command) =>
    Effect.gen(function* () {
      const result = yield* Deferred.make<{ sequence: number }, OrchestrationDispatchError>();
      yield* Queue.offer(commandQueue, {
        command,
        result,
        startedAtMs: yield* Clock.currentTimeMillis,
      });
      return yield* Deferred.await(result);
    });

  return {
    readEvents,
    dispatch,
    // Each access creates a fresh PubSub subscription so that multiple
    // consumers (wsServer, ProviderRuntimeIngestion, CheckpointReactor, etc.)
    // each independently receive all domain events.
    get streamDomainEvents(): OrchestrationEngineShape["streamDomainEvents"] {
      return Stream.fromPubSub(eventPubSub);
    },
    // Eager, scoped subscription: attaches to `eventPubSub` the moment the
    // effect runs so events published during a subsequent snapshot fetch are
    // buffered in the subscription queue instead of being lost in the
    // connect-gap. Returns a Stream over that already-attached subscription.
    subscribeDomainEvents: Effect.map(PubSub.subscribe(eventPubSub), (subscription) =>
      Stream.fromSubscription(subscription),
    ),
  } satisfies OrchestrationEngineShape;
});

export const OrchestrationEngineLive = Layer.effect(
  OrchestrationEngineService,
  makeOrchestrationEngine,
);

/**
 * ProjectionUsageLedgerRepository - Repository for the per-message usage
 * ledger behind the /usage dashboard (docs/usage-dashboard-design.md §3 D1).
 *
 * One row per `thread.token-usage.updated` runtime event: model attribution,
 * the four token buckets, and the provider-authoritative cost delta. Written
 * only by ProviderRuntimeIngestion (a side channel, not the projector);
 * `event_id` PK + INSERT OR IGNORE keeps replays from double-counting.
 *
 * @module ProjectionUsageLedgerRepository
 */
import { EventId, IsoDateTime, ThreadId, TurnId } from "@t3tools/contracts";
import * as Schema from "effect/Schema";
import * as Context from "effect/Context";
import type * as Effect from "effect/Effect";

import type { ProjectionRepositoryError } from "../Errors.ts";

export const ProjectionUsageLedgerRow = Schema.Struct({
  eventId: EventId,
  threadId: ThreadId,
  turnId: Schema.NullOr(TurnId),
  providerName: Schema.String,
  providerInstanceId: Schema.NullOr(Schema.String),
  requestedModel: Schema.NullOr(Schema.String),
  resolvedModel: Schema.NullOr(Schema.String),
  inputTokens: Schema.Number,
  cacheReadTokens: Schema.Number,
  cacheWriteTokens: Schema.Number,
  outputTokens: Schema.Number,
  costUsd: Schema.Number,
  createdAt: IsoDateTime,
});
export type ProjectionUsageLedgerRow = typeof ProjectionUsageLedgerRow.Type;

export interface ProjectionUsageLedgerRepositoryShape {
  /** Insert a ledger row; a replayed event id is silently ignored. */
  readonly insert: (
    row: ProjectionUsageLedgerRow,
  ) => Effect.Effect<void, ProjectionRepositoryError>;
}

export class ProjectionUsageLedgerRepository extends Context.Service<
  ProjectionUsageLedgerRepository,
  ProjectionUsageLedgerRepositoryShape
>()("t3/persistence/Services/ProjectionUsageLedger/ProjectionUsageLedgerRepository") {}

