  const markSourceProposedPlanImplemented = Effect.fn("markSourceProposedPlanImplemented")(
    function* (
      sourceThreadId: ThreadId,
      sourcePlanId: OrchestrationProposedPlanId,
      implementationThreadId: ThreadId,
      implementedAt: string,
    ) {
      const sourceThread = yield* resolveThreadDetail(sourceThreadId);
      const sourcePlan = sourceThread?.proposedPlans.find((entry) => entry.id === sourcePlanId);
      if (!sourceThread || !sourcePlan || sourcePlan.implementedAt !== null) {
        return;
      }

      const commandUuid = yield* crypto.randomUUIDv4;
      yield* orchestrationEngine.dispatch({
        type: "thread.proposed-plan.upsert",
        commandId: CommandId.make(
          `provider:source-proposed-plan-implemented:${implementationThreadId}:${commandUuid}`,
        ),
        threadId: sourceThread.id,
        proposedPlan: {
          ...sourcePlan,
          implementedAt,
          implementationThreadId,
          updatedAt: implementedAt,
        },
        createdAt: implementedAt,
      });
    },
  );

  const processRuntimeEvent = (event: ProviderRuntimeEvent) =>
    Effect.gen(function* () {
      // Account usage is account-scoped, not thread-scoped: feed it straight
      // into the shared registry keyed by provider instance. The runtime-event
      // envelope already carries the provider identity and timestamp, so the
      // adapter payload only needs the normalised windows + plan type.
      if (event.type === "account.rate-limits.updated") {
        yield* accountUsageRegistry.update({
          providerName: event.provider,
          providerInstanceId: event.providerInstanceId ?? null,
          windows: event.payload.windows,
          planType: event.payload.planType,
          observedAt: event.createdAt,
        });
        return;
      }

      const thread = yield* resolveThreadShell(event.threadId);
      if (!thread) return;

      // A queue update is inbound bookkeeping (e.g. the liveness sweep's own
      // recovery nudge being queued as a steer), not evidence the child is
      // making progress — letting it advance the heartbeat would reset the very
      // stall clock that triggered the nudge, making escalation unreachable.
      if (event.type !== "thread.queue.updated") {
        yield* touchHeartbeat(thread.id, event.createdAt);
      }

      // Usage ledger (docs/usage-dashboard-design.md §3 D1): one row per
      // token-usage event — model attribution, the four token buckets, and the
      // provider-authoritative cost delta. `event_id` PK + INSERT OR IGNORE
      // makes re-ingestion a no-op, so replays never double-count. `inputTokens`
      // keeps its context-window semantics (input + cacheRead + cacheWrite), so
      // the pure-input bucket is derived by subtracting the cache buckets.
      if (event.type === "thread.token-usage.updated" && event.payload.usage.usedTokens > 0) {
        const usage = event.payload.usage;
        const cacheRead = usage.cachedInputTokens ?? 0;
        const cacheWrite = usage.cacheWriteTokens ?? 0;
        yield* usageLedgerRepository
          .insert({
            eventId: event.eventId,
            threadId: thread.id,
            turnId: toTurnId(event.turnId) ?? null,
            providerName: event.provider,
            providerInstanceId: event.providerInstanceId ?? null,
            requestedModel: usage.model ?? null,
            resolvedModel: usage.resolvedModel ?? null,
            inputTokens: Math.max(0, (usage.inputTokens ?? 0) - cacheRead - cacheWrite),
            cacheReadTokens: cacheRead,
            cacheWriteTokens: cacheWrite,
            outputTokens: usage.outputTokens ?? 0,
            costUsd: usage.costUsd ?? 0,
            createdAt: event.createdAt,
          })
          .pipe(
            Effect.catchCause((cause) =>
              Effect.logWarning("provider runtime ingestion failed to write usage ledger row", {
                eventId: event.eventId,
                threadId: thread.id,
                cause: Cause.pretty(cause),
              }),
            ),
          );
      }

      let loadedThreadDetail: OrchestrationThread | null | undefined;
      const getLoadedThreadDetail = () =>
        Effect.gen(function* () {
          if (loadedThreadDetail !== undefined) {
            return loadedThreadDetail;
          }
          loadedThreadDetail = (yield* resolveThreadDetail(thread.id)) ?? null;
          return loadedThreadDetail;
        });

      const now = event.createdAt;
      const eventTurnId = toTurnId(event.turnId);
      const activeTurnId = thread.session?.activeTurnId ?? null;

      const conflictsWithActiveTurn =
        activeTurnId !== null && eventTurnId !== undefined && !sameId(activeTurnId, eventTurnId);
      const missingTurnForActiveTurn = activeTurnId !== null && eventTurnId === undefined;

      // A turn.started that conflicts with the active turn is legitimate when
      // the server itself has a turn start pending for this thread AND the
      // provider session already tracks the event's turn as its active turn:
      // steering a running turn makes some providers (e.g. opencode) open a
      // new turn without ever completing the superseded one. A stale
      // turn.started for some other turn id still gets rejected.
